window.kbPageData["views/entry/k-db2e693741c98433"] = {"key":"entry/k-db2e693741c98433","state":{"route":"entry/k-db2e693741c98433"},"node":{"id":"k-db2e693741c98433","mode":"k","title":"不敢腐不能腐不想腐","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"2.不敢腐不能腐不想腐\n“不敢”是前提，要以严格的执纪执法增强制度刚性，让党员、干部从害怕被查处的\n“不敢”走向敬畏党和人民、敬畏党纪国法的“不敢”;\n“不能”是关键，要科学配置权力，加强重点领域监督机制改革和制度建设，推动\n形成不断完备的制度体系、严格有效的监督体系；\n“不想”是根本，要靠加强理想…","sources":[{"id":"5e7483966a872659","label":"不敢腐不能腐不想腐","topic":"党政制度与理论","category":"非时政","text":"2.不敢腐不能腐不想腐\n“不敢”是前提，要以严格的执纪执法增强制度刚性，让党员、干部从害怕被查处的\n“不敢”走向敬畏党和人民、敬畏党纪国法的“不敢”;\n“不能”是关键，要科学配置权力，加强重点领域监督机制改革和制度建设，推动\n形成不断完备的制度体系、严格有效的监督体系；\n“不想”是根本，要靠加强理想信念教育、提高党性觉悟、涵养廉洁文化，筑牢拒腐防\n变的思想道德防线，夯实不忘初心、 牢记使命的思想根基。\n一体推进不敢腐、不能腐、不想腐，必须三者同时发力、同向发力、综合发力，把不敢腐\n的强大震慑效能、不能腐的刚性制度约束、不想腐的思想教育优势融于一体。","source":{"doc":"41195a191a57c1c36332","first":18,"last":19,"page":18,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-db2e693741c98433":[]}};
